    const q0=rig.quaternion.clone(), q1=new THREE.Quaternion().setFromUnitVectors(V3(0,0,1),this.SUN), fw=this.SUN; this.near.L.forEach(o=>{ const a=o.p.clone().sub(rig.position), z=a.dot(fw), l=a.clone().addScaledVector(fw,-z), L=l.length(); if(L<o.r*1.6+14) o.p.add(l.normalize().multiplyScalar(o.r*1.6+14-L)); }); let v=0; const mf=this.tick(dt=>{ rig.position.addScaledVector(fw,v*dt); this.shake(.004+.00004*v,.2); this.J.cam(); }); const turn=over(3,e=>rig.quaternion.copy(q0).slerp(q1,e)); over(7,e=>v=70*e*e); S.phase='play';
